// ══════════════════════════════════════
// DATE RANGE INPUT (날짜 직접 입력)
// ══════════════════════════════════════
function DateRangeInputs({ dates, dateRange, setDateRange }) {
  const [startInput, setStartInput] = useState("");
  const [endInput, setEndInput] = useState("");

  // Sync display values when dateRange changes
  useEffect(() => {
    if (!dates) return;
    setStartInput(dates[dateRange[0]] || "");
    setEndInput(dates[dateRange[1]] || "");
  }, [dates, dateRange]);

  // Find the closest date index (on or after the input)
  const findDateIndex = useCallback((dateStr, direction) => {
    if (!dates || !dateStr) return -1;
    // Normalize input: allow "2015-1" → "2015-01-01", "2015" → "2015-01-01"
    let normalized = dateStr.trim();
    if (/^\d{4}$/.test(normalized)) normalized += "-01-01";
    else if (/^\d{4}-\d{1,2}$/.test(normalized)) {
      const [y, m] = normalized.split("-");
      normalized = y + "-" + m.padStart(2, "0") + "-01";
    } else if (/^\d{4}-\d{1,2}-\d{1,2}$/.test(normalized)) {
      const [y, m, d] = normalized.split("-");
      normalized = y + "-" + m.padStart(2, "0") + "-" + d.padStart(2, "0");
    }
    // Exact match first
    const exact = dates.indexOf(normalized);
    if (exact !== -1) return exact;
    // Find nearest
    if (direction === "start") {
      for (let i = 0; i < dates.length; i++) { if (dates[i] >= normalized) return i; }
      return dates.length - 1;
    } else {
      for (let i = dates.length - 1; i >= 0; i--) { if (dates[i] <= normalized) return i; }
      return 0;
    }
  }, [dates]);

  const applyStart = useCallback(() => {
    const idx = findDateIndex(startInput, "start");
    if (idx >= 0 && idx < dateRange[1]) {
      setDateRange([idx, dateRange[1]]);
    }
  }, [startInput, dateRange, findDateIndex, setDateRange]);

  const applyEnd = useCallback(() => {
    const idx = findDateIndex(endInput, "end");
    if (idx >= 0 && idx > dateRange[0]) {
      setDateRange([dateRange[0], idx]);
    }
  }, [endInput, dateRange, findDateIndex, setDateRange]);

  const inputStyle = {
    width: 110, padding: "5px 8px", fontSize: 13, fontWeight: 600,
    border: "1px solid #d0d5dd", borderRadius: 6, color: "#000",
    background: "#fff", textAlign: "center", outline: "none",
    fontFamily: "'Pretendard', sans-serif",
  };

  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
      <span style={{ fontSize: 12, fontWeight: 700, color: "#000" }}>기간</span>
      <input
        value={startInput}
        onChange={e => setStartInput(e.target.value)}
        onBlur={applyStart}
        onKeyDown={e => e.key === "Enter" && applyStart()}
        placeholder="2015-01-01"
        style={inputStyle}
      />
      <span style={{ fontSize: 13, color: "#000", fontWeight: 600 }}>~</span>
      <input
        value={endInput}
        onChange={e => setEndInput(e.target.value)}
        onBlur={applyEnd}
        onKeyDown={e => e.key === "Enter" && applyEnd()}
        placeholder="2026-03-31"
        style={inputStyle}
      />
      <span style={{ fontSize: 11, color: "#94a3b8" }}>
        (yyyy-mm-dd, yyyy-mm, yyyy)
      </span>
    </div>
  );
}

export default function YieldDashboard() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState(["BOK_Base", "KTB_3Y", "KTB_10Y"]);
  const [axisMap, setAxisMap] = useState({});
  const [dateRange, setDateRange] = useState([0, 0]);
  const [yLeftRange, setYLeftRange] = useState([1.5, 5.5]);
  const [yRightRange, setYRightRange] = useState([0, 200]);
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState("");
  const [importType, setImportType] = useState("ktb");
  const [importMsg, setImportMsg] = useState("");
  const [showControls, setShowControls] = useState(true);
  const [yLeftAuto, setYLeftAuto] = useState(true);
  const [yRightAuto, setYRightAuto] = useState(true);

  // Initialize data
  useEffect(() => {
    let stored = loadFromStorage();
    // Reset if stored data is smaller than built-in data (version upgrade)
    if (!stored || !stored.dates || stored.dates.length < INIT_DATES.length) {
      stored = { dates: INIT_DATES, series: INIT_SERIES };
      saveToStorage(stored);
    }
    setData(stored);
    setDateRange([Math.max(0, stored.dates.length - 260), stored.dates.length - 1]);
    setLoading(false);
  }, []);

  // Default axis assignment: % -> left, bp -> right
  useEffect(() => {
    const map = {};
    selected.forEach(id => {
      const cfg = SERIES_MAP[id];
      if (!map[id]) map[id] = cfg?.unit === "bp" ? "right" : "left";
    });
    setAxisMap(prev => ({ ...prev, ...Object.fromEntries(selected.filter(id => !prev[id]).map(id => [id, map[id]])) }));
  }, [selected]);

  // Auto y-axis range
  useEffect(() => {
    if (!data) return;
    const [si, ei] = dateRange;
    const leftIds = selected.filter(id => axisMap[id] !== "right");
    const rightIds = selected.filter(id => axisMap[id] === "right");

    if (yLeftAuto && leftIds.length > 0) {
      let min = Infinity, max = -Infinity;
      leftIds.forEach(id => {
        const vals = (data.series[id] || []).slice(si, ei + 1).filter(v => v != null);
        vals.forEach(v => { if (v < min) min = v; if (v > max) max = v; });
      });
      if (min !== Infinity) {
        const pad = (max - min) * 0.08 || 0.2;
        setYLeftRange([Math.floor((min - pad) * 20) / 20, Math.ceil((max + pad) * 20) / 20]);
      }
    }
    if (yRightAuto && rightIds.length > 0) {
      let min = Infinity, max = -Infinity;
      rightIds.forEach(id => {
        const vals = (data.series[id] || []).slice(si, ei + 1).filter(v => v != null);
        vals.forEach(v => { if (v < min) min = v; if (v > max) max = v; });
      });
      if (min !== Infinity) {
        const pad = (max - min) * 0.08 || 10;
        setYRightRange([Math.floor(min - pad), Math.ceil(max + pad)]);
      }
    }
  }, [data, selected, axisMap, dateRange, yLeftAuto, yRightAuto]);

  const toggleSeries = (id) => {
    setSelected(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  };

  const toggleAxis = (id) => {
    setAxisMap(prev => ({ ...prev, [id]: prev[id] === "right" ? "left" : "right" }));
  };

  const handleImport = async () => {
    if (!importText.trim()) return;
    const parsed = parseInputData(importText, importType);
    if (!parsed || Object.keys(parsed).length === 0) {
      setImportMsg("❌ 파싱 실패: 데이터 형식을 확인하세요");
      return;
    }
    const merged = mergeData(data, parsed, importType);
    setData(merged);
    saveToStorage(merged);
    setDateRange([Math.max(0, merged.dates.length - 260), merged.dates.length - 1]);
    setImportMsg("✅ " + Object.keys(parsed).length + "일 데이터 업데이트 완료");
    setImportText("");
    setTimeout(() => setImportMsg(""), 3000);
  };

  const handleReset = async () => {
    const fresh = { dates: INIT_DATES, series: INIT_SERIES };
    setData(fresh);
    saveToStorage(fresh);
    setDateRange([Math.max(0, fresh.dates.length - 260), fresh.dates.length - 1]);
  };

  const groups = [
    { key: "base", title: "기준금리", items: ALL_SERIES.filter(s => s.group === "base") },
    { key: "ktb", title: "국고채", items: ALL_SERIES.filter(s => s.group === "ktb") },
    { key: "credit", title: "크레딧 3년", items: ALL_SERIES.filter(s => s.group === "credit") },
    { key: "spread", title: "스프레드 (vs 국고3년)", items: ALL_SERIES.filter(s => s.group === "spread") },
  ];

  if (loading) {
    return (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "100vh", background: "#fff", fontFamily: "'Pretendard', sans-serif" }}>
        <div style={{ textAlign: "center", color: "#64748b" }}>
          <div style={{ fontSize: 28, marginBottom: 8 }}>📊</div>
          <div style={{ fontSize: 13 }}>금리 데이터 로딩 중...</div>
        </div>
      </div>
    );
  }

  const dateLabels = data ? [data.dates[dateRange[0]] || "", data.dates[dateRange[1]] || ""] : ["", ""];

  return (
    <div style={{ display: "flex", height: "100vh", background: "#fff", fontFamily: "'Pretendard', -apple-system, BlinkMacSystemFont, sans-serif", color: "#0f172a", overflow: "hidden" }}>
      {/* LEFT PANEL - Controls */}
      <div style={{
        width: showControls ? 260 : 0, minWidth: showControls ? 260 : 0,
        borderRight: showControls ? "1px solid #e2e8f0" : "none",
        overflow: "hidden", transition: "all 0.2s", display: "flex", flexDirection: "column",
      }}>
        <div style={{ padding: "14px 16px 8px", borderBottom: "1px solid #e2e8f0" }}>
          <div style={{ fontSize: 14, fontWeight: 700, color: "#0046ff", letterSpacing: -0.3 }}>📊 금리 차트</div>
          <div style={{ fontSize: 10, color: "#94a3b8", marginTop: 2 }}>시리즈 선택 · 축 배정</div>
        </div>

        <div style={{ flex: 1, overflow: "auto", padding: "8px 12px" }}>
          {groups.map(g => (
            <div key={g.key} style={{ marginBottom: 12 }}>
              <div style={{ fontSize: 10, fontWeight: 700, color: "#0046ff", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4, padding: "4px 0", borderBottom: "1px solid #f1f5f9" }}>
                {g.title}
              </div>
              {g.items.map(s => {
                const isSelected = selected.includes(s.id);
                const axis = axisMap[s.id] || "left";
                return (
                  <div key={s.id} style={{ display: "flex", alignItems: "center", gap: 4, padding: "3px 0", fontSize: 11 }}>
                    <input type="checkbox" checked={isSelected} onChange={() => toggleSeries(s.id)}
                      style={{ accentColor: s.color, width: 13, height: 13, cursor: "pointer" }} />
                    <span style={{
                      width: 10, height: 10, borderRadius: 2,
                      background: s.dash ? "none" : s.color,
                      border: s.dash ? `2px dashed ${s.color}` : "none",
                      flexShrink: 0,
                    }} />
                    <span style={{ flex: 1, color: isSelected ? "#0f172a" : "#94a3b8", cursor: "pointer", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}
                      onClick={() => toggleSeries(s.id)}>
                      {s.label}
                    </span>
                    {isSelected && (
                      <button onClick={() => toggleAxis(s.id)} style={{
                        fontSize: 9, padding: "1px 4px", borderRadius: 3, cursor: "pointer",
                        background: axis === "right" ? "#f1f5f9" : "#0046ff10",
                        color: axis === "right" ? "#64748b" : "#0046ff",
                        border: `1px solid ${axis === "right" ? "#e2e8f0" : "#0046ff30"}`,
                        fontWeight: 600,
                      }}>
                        {axis === "right" ? "R" : "L"}
                      </button>
                    )}
                  </div>
                );
              })}
            </div>
          ))}

          {/* Y-axis range controls */}
          <div style={{ marginTop: 8, padding: "8px 0", borderTop: "1px solid #f1f5f9" }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: "#0046ff", marginBottom: 6 }}>Y축 범위</div>
            {["left", "right"].map(side => {
              const range = side === "left" ? yLeftRange : yRightRange;
              const setRange = side === "left" ? setYLeftRange : setYRightRange;
              const auto = side === "left" ? yLeftAuto : yRightAuto;
              const setAuto = side === "left" ? setYLeftAuto : setYRightAuto;
              const hasSeries = selected.some(id => (axisMap[id] || "left") === side);
              if (!hasSeries) return null;
              return (
                <div key={side} style={{ marginBottom: 6 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 4, marginBottom: 3 }}>
                    <span style={{ fontSize: 10, color: "#64748b", fontWeight: 600 }}>{side === "left" ? "좌축" : "우축"}</span>
                    <label style={{ display: "flex", alignItems: "center", gap: 2, fontSize: 9, color: "#94a3b8", cursor: "pointer" }}>
                      <input type="checkbox" checked={auto} onChange={() => setAuto(!auto)} style={{ width: 10, height: 10 }} /> auto
                    </label>
                  </div>
                  {!auto && (
                    <div style={{ display: "flex", gap: 4, alignItems: "center" }}>
                      <input type="number" value={range[0]} step={side === "right" ? 10 : 0.1}
                        onChange={e => setRange([parseFloat(e.target.value) || 0, range[1]])}
                        style={{ width: 52, padding: "2px 4px", fontSize: 10, border: "1px solid #e2e8f0", borderRadius: 4, textAlign: "center" }} />
                      <span style={{ fontSize: 9, color: "#94a3b8" }}>~</span>
                      <input type="number" value={range[1]} step={side === "right" ? 10 : 0.1}
                        onChange={e => setRange([range[0], parseFloat(e.target.value) || 0])}
                        style={{ width: 52, padding: "2px 4px", fontSize: 10, border: "1px solid #e2e8f0", borderRadius: 4, textAlign: "center" }} />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Bottom buttons */}
        <div style={{ padding: "8px 12px", borderTop: "1px solid #e2e8f0", display: "flex", gap: 6 }}>
          <button onClick={() => setShowImport(!showImport)} style={{
            flex: 1, padding: "6px", borderRadius: 6, border: "1px solid #0046ff30", background: showImport ? "#0046ff10" : "#fff",
            color: "#0046ff", fontSize: 10, fontWeight: 600, cursor: "pointer",
          }}>📥 데이터 입력</button>
          <button onClick={handleReset} style={{
            padding: "6px 10px", borderRadius: 6, border: "1px solid #e2e8f0", background: "#fff",
            color: "#94a3b8", fontSize: 10, cursor: "pointer",
          }}>초기화</button>
        </div>
      </div>

      {/* MAIN AREA */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}>
        {/* Toggle sidebar button */}
        <div style={{ display: "flex", alignItems: "center", padding: "6px 16px", borderBottom: "1px solid #f1f5f9", gap: 8 }}>
          <a href="/" style={{ fontSize: 11, color: "#94a3b8", textDecoration: "none", marginRight: 8 }}>← 컨트롤타워</a>
          <button onClick={() => setShowControls(!showControls)} style={{
            padding: "3px 8px", borderRadius: 4, border: "1px solid #e2e8f0", background: "#fff",
            color: "#64748b", fontSize: 11, cursor: "pointer",
          }}>{showControls ? "◀" : "▶ 설정"}</button>
          <span style={{ fontSize: 14, fontWeight: 700, color: "#000" }}>
            {dateLabels[0]} ~ {dateLabels[1]}
          </span>
          <span style={{ fontSize: 12, color: "#000", marginLeft: "auto" }}>
            {data?.dates?.length || 0}일 · {data?.dates?.[0]?.slice(0,4) || ''}~{data?.dates?.[data.dates.length-1]?.slice(0,4) || ''}
          </span>
        </div>

        {/* Chart */}
        <div style={{ flex: 1, padding: "8px 16px 0", position: "relative", minHeight: 0 }}>
          <CustomLegend selected={selected} axisMap={axisMap} />
          <div style={{ height: "calc(100% - 40px)", position: "relative" }}>
            <YieldChart
              data={data} selected={selected} axisMap={axisMap}
              dateRange={dateRange} yLeftRange={yLeftRange} yRightRange={yRightRange}
            />
          </div>
        </div>

        {/* Date Range Slider */}
        <div style={{ padding: "4px 20px 12px" }}>
          <DateRangeInputs dates={data?.dates} dateRange={dateRange} setDateRange={setDateRange} />
          <RangeSlider
            min={0} max={(data?.dates?.length || 1) - 1}
            value={dateRange} onChange={setDateRange}
            dates={data?.dates}
          />
          {/* Quick range buttons */}
          <div style={{ display: "flex", gap: 4, marginTop: 4 }}>
            {[
              { label: "3M", days: 65 }, { label: "6M", days: 130 },
              { label: "1Y", days: 260 }, { label: "3Y", days: 780 },
              { label: "5Y", days: 1300 }, { label: "10Y", days: 2600 },
              { label: "전체", days: 99999 },
            ].map(r => (
              <button key={r.label} onClick={() => {
                const end = (data?.dates?.length || 1) - 1;
                setDateRange([Math.max(0, end - r.days), end]);
              }} style={{
                padding: "4px 10px", borderRadius: 4, border: "1px solid #d0d5dd",
                background: "#fff", color: "#000", fontSize: 12, fontWeight: 600, cursor: "pointer",
              }}>{r.label}</button>
            ))}
          </div>
        </div>

        {/* Import Panel */}
        {showImport && (
          <div style={{ borderTop: "1px solid #e2e8f0", padding: "12px 16px", maxHeight: 220, overflow: "auto" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
              <span style={{ fontSize: 11, fontWeight: 600, color: "#0f172a" }}>데이터 입력</span>
              <select value={importType} onChange={e => setImportType(e.target.value)} style={{
                padding: "3px 6px", borderRadius: 4, border: "1px solid #e2e8f0", fontSize: 10,
                color: "#334155", background: "#fff",
              }}>
                <option value="ktb">국고채</option>
                <option value="agency">특수채AAA</option>
                <option value="bank">은행채AAA</option>
                <option value="corp_aa">회사채AA-</option>
                <option value="corp_a">회사채A+</option>
                <option value="fin_aa">기타금융채AA-</option>
                <option value="fin_a">기타금융채A+</option>
              </select>
              <button onClick={handleImport} style={{
                padding: "4px 12px", borderRadius: 6, border: "none", background: "#0046ff",
                color: "#fff", fontSize: 10, fontWeight: 600, cursor: "pointer",
              }}>업데이트</button>
            </div>
            <textarea value={importText} onChange={e => setImportText(e.target.value)}
              placeholder={"기존 데이터와 동일한 형식으로 붙여넣기\n(날짜\t3M\t6M\t...\t50Y 형식)"}
              style={{
                width: "100%", height: 120, padding: 8, borderRadius: 6, border: "1px solid #e2e8f0",
                fontSize: 10, fontFamily: "monospace", color: "#334155", background: "#f8fafc",
                resize: "vertical",
              }} />
            {importMsg && <div style={{ fontSize: 11, color: importMsg.startsWith("✅") ? "#16a34a" : "#dc2626", marginTop: 4 }}>{importMsg}</div>}
            <div style={{ fontSize: 9, color: "#94a3b8", marginTop: 4 }}>
              * 데이터 소스에서 복사 → 위 칸에 붙여넣기 → 소스 타입 선택 → 업데이트. 기존 데이터에 새 날짜가 추가/업데이트됩니다.
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
